    const row = newId ? viewTags(nv).find((t) => t.id === newId) : undefined;
    if (row) { if (/^pending-/.test(row.id)) row.id = "g" + Date.now().toString(36); edited.push(row.id); }
    postViews(nv, edited);
    return;
