    const where = browseRouteNow();
    const sb = el("span", "ctx-item-sub");
    sb.textContent = "the session's working tree, " + (where === "pane" ? "in the Files pane" : "in a viewer over this chat");
    bodyEl.appendChild(sb);
    browse.appendChild(bodyEl);
